class Solution {
public:
    int evalRPN(vector<string>& tokens) {
        vector<int> st;
        st.reserve(tokens.size());
        for (const string& t : tokens) {
            if (t == "+" || t == "-" || t == "*" || t == "/") {
                int b = st.back(); st.pop_back();
                int a = st.back(); st.pop_back();
                long long res = 0;
                if (t == "+") res = (long long)a + b;
                else if (t == "-") res = (long long)a - b;
                else if (t == "*") res = (long long)a * b;
                else /* t == "/" */ res = b == 0 ? 0 : (long long)a / b; // truncates toward zero
                st.push_back((int)res);
            } else {
                st.push_back(stoi(t));
            }
        }
        return st.back();
    }
};
